# Check what directories exist and look for data files
import os
import sys

print("Current working directory:", os.getcwd())
print("\nListing root directory:")
try:
    root_items = os.listdir('/')
    print(root_items)
except Exception as e:
    print(f"Error listing root: {e}")

print("\nChecking /mnt directory:")
try:
    mnt_items = os.listdir('/mnt')
    print(mnt_items)
except Exception as e:
    print(f"Error listing /mnt: {e}")

# Try to find any data directory
possible_dirs = ['/data', '/mnt/data', '/home/jovyan/data', '/home/jovyan/work', '.']
for dir_path in possible_dirs:
    if os.path.exists(dir_path):
        print(f"\nDirectory exists: {dir_path}")
        try:
            files = os.listdir(dir_path)
            print(f"Files in {dir_path}: {files[:20]}")
            # Look for database files
            db_files = [f for f in files if f.endswith('.db') or f.endswith('.sqlite') or f.endswith('.sqlite3')]
            if db_files:
                print(f"Database files found: {db_files}")
                break
        except Exception as e:
            print(f"Error listing {dir_path}: {e}")

# If we still can't find it, check if there are any CSV or other data files
print("\nSearching for any data files...")
for dir_path in possible_dirs:
    if os.path.exists(dir_path):
        try:
            files = os.listdir(dir_path)
            data_files = [f for f in files if f.endswith('.csv') or f.endswith('.json') or f.endswith('.parquet') or 'jira' in f.lower() or 'risk' in f.lower()]
            if data_files:
                print(f"Data files in {dir_path}: {data_files}")
        except:
            pass
